import React, { useState, useEffect } from 'react';

function CluePage({ teamId, setCurrentPage }) {
  // Treasure hunt clues and answers
  const treasureHunt = [
    {
      clue: "I'm tall when I'm young, and short when I'm old. What am I?",
      answer: "candle"
    },
    {
      clue: "I have cities, but no houses. I have mountains, but no trees. I have water, but no fish. What am I?",
      answer: "map"
    },
    {
      clue: "What has keys but no locks, space but no room, and you can enter but not go in?",
      answer: "keyboard"
    },
    {
      clue: "The more you take, the more you leave behind. What am I?",
      answer: "footsteps"
    },
    {
      clue: "I'm found in the sea and on land but I don't walk or swim. I travel by foot but I have no toes. No matter where I go, I'm never far from home. What am I?",
      answer: "snail"
    },
    {
      clue: "I have branches, but no fruit, trunk or leaves. What am I?",
      answer: "bank"
    },
    {
      clue: "What building has the most stories?",
      answer: "library"
    },
    {
      clue: "What can travel around the world while staying in a corner?",
      answer: "stamp"
    },
    {
      clue: "I'm light as a feather, but the strongest person can't hold me for more than a few minutes. What am I?",
      answer: "breath"
    },
    {
      clue: "The person who makes it, sells it. The person who buys it, never uses it. The person who uses it, never sees it. What is it?",
      answer: "coffin"
    }
  ];

  // Game state
  const [currentClueIndex, setCurrentClueIndex] = useState(0);
  const [answer, setAnswer] = useState('');
  const [result, setResult] = useState({ message: '', isCorrect: null });
  const [startTime] = useState(Date.now());
  const [completionTime, setCompletionTime] = useState(null);

  // Handle form submission
  const handleSubmit = (e) => {
    e.preventDefault();

    const userAnswer = answer.trim().toLowerCase();
    const correctAnswer = treasureHunt[currentClueIndex].answer;

    if (userAnswer === correctAnswer) {
      // Correct answer
      setResult({ message: "Correct! Moving to the next clue...", isCorrect: true });

      // Move to next clue
      if (currentClueIndex < treasureHunt.length - 1) {
        setTimeout(() => {
          setCurrentClueIndex(prevIndex => prevIndex + 1);
          setAnswer('');
          setResult({ message: '', isCorrect: null });
        }, 1500);
      } else {
        // Game completed
        const totalTime = Math.floor((Date.now() - startTime) / 1000);
        setCompletionTime(totalTime);

        // Save completion data to localStorage
        const teamName = localStorage.getItem('treasureHunt_teamName');
        const members = localStorage.getItem('treasureHunt_members') || '';

        // Get existing leaderboard data or initialize empty array
        const existingLeaderboard = JSON.parse(localStorage.getItem('treasureHunt_leaderboard') || '[]');

        // Add current team's data
        const teamData = {
          teamId,
          teamName,
          completionTime: totalTime,
          members,
          completedAt: new Date().toISOString()
        };

        // Check if team already exists in leaderboard
        const existingTeamIndex = existingLeaderboard.findIndex(entry => entry.teamId === teamId);

        if (existingTeamIndex >= 0) {
          // Update existing entry if this time is better
          if (totalTime < existingLeaderboard[existingTeamIndex].completionTime) {
            existingLeaderboard[existingTeamIndex] = teamData;
          }
        } else {
          // Add new entry
          existingLeaderboard.push(teamData);
        }

        // Sort by completion time (fastest first)
        existingLeaderboard.sort((a, b) => a.completionTime - b.completionTime);

        // Save updated leaderboard
        localStorage.setItem('treasureHunt_leaderboard', JSON.stringify(existingLeaderboard));
      }
    } else {
      // Incorrect answer
      setResult({ message: "Incorrect answer. Try again!", isCorrect: false });
    }
  };

  // Function to view leaderboard
  const viewLeaderboard = () => {
    setCurrentPage('leaderboard');
  };

  return (
    <div className="clue-container">
      <h1>Treasure Hunt</h1>

      {completionTime ? (
        <div className="completion-container">
          <h2>Congratulations! You've found the treasure!</h2>
          <p className="completion-time">
            You completed the hunt in {Math.floor(completionTime / 60)} minutes and {completionTime % 60} seconds.
          </p>
          <button onClick={viewLeaderboard} className="leaderboard-button">
            View Leaderboard
          </button>
        </div>
      ) : (
        <>
          <div className="clue-box">
            <p>{treasureHunt[currentClueIndex].clue}</p>
          </div>

          <form onSubmit={handleSubmit} className="answer-form">
            <input
              type="text"
              value={answer}
              onChange={(e) => setAnswer(e.target.value)}
              placeholder="Enter your answer"
              required
              className="answer-input"
            />
            <button type="submit" className="submit-button">
              Submit
            </button>
          </form>

          {result.message && (
            <div className={`result ${result.isCorrect ? 'correct' : 'incorrect'}`}>
              {result.message}
            </div>
          )}

          <div className="progress">
            Clue: {currentClueIndex + 1}/{treasureHunt.length}
          </div>
        </>
      )}
    </div>
  );
}

export default CluePage;
